plist.dict:
CFBundlePackageType
APPL
CFBundleName
{{.Info.ProductName}}
CFBundleExecutable
{{.OutputFilename}}
CFBundleIdentifier
com.fiko942.{{safeBundleID .Name}}
CFBundleVersion
{{.Info.ProductVersion}}
CFBundleGetInfoString
{{.Info.Comments}}
CFBundleShortVersionString
{{.Info.ProductVersion}}
CFBundleIconFile
iconfile
LSMinimumSystemVersion
10.13.0
NSHighResolutionCapable
true
NSHumanReadableCopyright
{{.Info.Copyright}}
NSMicrophoneUsageDescription
AetherGrok requires microphone access for voice dictation and speech-to-text input.
NSSpeechRecognitionUsageDescription
AetherGrok uses speech recognition to convert dictated voice prompts into text.
NSAppleEventsUsageDescription
AetherGrok requires automation access to coordinate workflow tasks.
{{if .Info.FileAssociations}}
CFBundleDocumentTypes

  {{range .Info.FileAssociations}}

    CFBundleTypeExtensions

      {{.Ext}}

    CFBundleTypeName
    {{.Name}}
    CFBundleTypeRole
    {{.Role}}
    CFBundleTypeIconFile
    {{.IconName}}

  {{end}}

{{end}}
{{if .Info.Protocols}}
CFBundleURLTypes

  {{range .Info.Protocols}}

        CFBundleURLName
        com.fiko942.{{.Scheme}}
        CFBundleURLSchemes

            {{.Scheme}}

        CFBundleTypeRole
        {{.Role}}

  {{end}}

{{end}}
